#!/bin/sh
# Writes the app's config.js from environment variables when the container starts.
set -e
mkdir -p /etc/medialoader

esc() { printf '%s' "$1" | sed "s/\\\\/\\\\\\\\/g; s/'/\\\\'/g"; }

cat > /etc/medialoader/config.js <<EOF
/* Generated by the MediaLoader container at $(date -u +%Y-%m-%dT%H:%M:%SZ) */
var MEDIALOADER_DEFAULTS = {
    tv:    { url: '$(esc "${SONARR_URL:-http://media-server:8989}")', apiKey: '$(esc "${SONARR_API_KEY}")', qualityProfile: '$(esc "${SONARR_QUALITY_PROFILE:-HD-1080p}")' },
    movie: { url: '$(esc "${RADARR_URL:-http://media-server:7878}")', apiKey: '$(esc "${RADARR_API_KEY}")', qualityProfile: '$(esc "${RADARR_QUALITY_PROFILE:-Low Quality 1080}")' },
    music: { url: '$(esc "${LIDARR_URL:-http://media-server:8686}")', apiKey: '$(esc "${LIDARR_API_KEY}")', qualityProfile: '$(esc "${LIDARR_QUALITY_PROFILE}")' }
};
var MEDIALOADER_PLEX = { url: '$(esc "${PLEX_URL:-http://<plex-server-ip>:32400}")', token: '$(esc "${PLEX_TOKEN}")' };
var MEDIALOADER_TMDB = { token: '$(esc "${TMDB_TOKEN}")' };
EOF

echo "MediaLoader config written (Sonarr key: ${SONARR_API_KEY:+set}${SONARR_API_KEY:-MISSING}, Radarr key: ${RADARR_API_KEY:+set}${RADARR_API_KEY:-MISSING}, Lidarr key: ${LIDARR_API_KEY:+set}${LIDARR_API_KEY:-MISSING})"
